#include "zs_mesh.h"
void zs_mesh_init(zs_mesh_sm_t*s){s->state=ZS_LORA_SLEEP;s->cellular_ok=true;s->pending_p0=false;s->now_ms=0;s->deadline_ms=0;s->beacon_interval_ms=10000;s->rx_window_ms=500;s->active_window_ms=90000;s->route_hops=0;}
void zs_mesh_set_cellular(zs_mesh_sm_t*s,bool ok,uint32_t now){s->cellular_ok=ok;s->now_ms=now;if(ok&&s->state==ZS_LORA_DISCOVERY)s->state=ZS_LORA_SLEEP;}
void zs_mesh_set_pending_p0(zs_mesh_sm_t*s,bool p0,uint32_t now){s->pending_p0=p0;s->now_ms=now;if(p0&&!s->cellular_ok){s->state=ZS_LORA_DISCOVERY;s->deadline_ms=now+30000;}}
zs_lora_state_t zs_mesh_step(zs_mesh_sm_t*s,uint32_t now){s->now_ms=now;if(s->cellular_ok){if(s->pending_p0){s->state=ZS_LORA_SLEEP;return s->state;}if(s->state==ZS_LORA_SLEEP&&now>=s->deadline_ms){s->state=ZS_LORA_GATEWAY_BEACON;s->deadline_ms=now+10;}else if(s->state==ZS_LORA_GATEWAY_BEACON&&now>=s->deadline_ms){s->state=ZS_LORA_GATEWAY_RX;s->deadline_ms=now+s->rx_window_ms;}else if(s->state==ZS_LORA_GATEWAY_RX&&now>=s->deadline_ms){s->state=ZS_LORA_SLEEP;s->deadline_ms=now+s->beacon_interval_ms;}return s->state;}if(s->pending_p0){if(s->state==ZS_LORA_DISCOVERY&&s->route_hops>0&&s->route_hops<=5){s->state=ZS_LORA_MESH_ACTIVE;s->deadline_ms=now+s->active_window_ms;}else if(s->state==ZS_LORA_DISCOVERY&&now>=s->deadline_ms){s->state=ZS_LORA_STORE_FORWARD;}else if(s->state==ZS_LORA_MESH_ACTIVE&&!s->pending_p0&&now>=s->deadline_ms){s->state=ZS_LORA_SLEEP;}}return s->state;}
